import {MAX_GUESSES,normalizeName,ageOn,drawNext,createRound,submitGuess} from './engine.js';
import {revealSequence} from './reveal.js';
import {findPlayers} from './player-search.js';
import {BONUS_PLAYER,isBonusRound,openingRound,searchRosterForRound} from './bonus.js';
const $=id=>document.getElementById(id);
const STORAGE='pixel-scout-v1';
const LEAGUES={PL:'Premier League',LaLiga:'LaLiga',SerieA:'Serie A',Ligue1:'Ligue 1'};
const POSITIONS={GK:'Kaleci',DF:'Defans',MF:'Orta saha',FW:'Forvet'};
const COLORS={exact:'Doğru',league:'Aynı lig, farklı kulüp',miss:'Farklı',unknown:'Kaynakta bilgi yok'};
let players=[],searchPlayers=[],data={},round=null,bag={},league='all',roundNumber=0,clueOpen=false,suggestions=[],activeIndex=-1,sessionWins=0,revealing=false,cancelReveal=null,revealActions=[];
let stats={played:0,won:0,streak:0,bestStreak:0,distribution:Array(8).fill(0)};
let storageAvailable=true;
function readStorage(){try{return JSON.parse(localStorage.getItem(STORAGE))||{};}catch{return {};}}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify({snapshotDate:data.snapshotDate,round:{targetId:round.targetId,mode:round.mode,guessIds:round.guessIds},bag,league,roundNumber,clueOpen,stats}));}catch{storageAvailable=false;}}
function cleanStats(s){const int=v=>Number.isSafeInteger(v)&&v>=0?v:0;const out={played:int(s?.played),won:int(s?.won),streak:int(s?.streak),bestStreak:int(s?.bestStreak),distribution:Array.from({length:8},(_,i)=>int(s?.distribution?.[i]))};out.won=Math.min(out.won,out.played);out.streak=Math.min(out.streak,out.won);out.bestStreak=Math.max(out.streak,Math.min(out.bestStreak,out.won));return out;}
function eligible(){return players.filter(p=>league==='all'||p.league===league);}
function target(){return isBonusRound(round)?BONUS_PLAYER:players.find(p=>p.id===round?.targetId);}
function currentRoster(){return searchRosterForRound(round,searchPlayers);}
function element(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e;}
function flag(p){const code=p.nationalityCode||'?';const drawn=['FR','NO','ENG','BE','ES','IT','AR','NL','MA','PT','BR','TR'].includes(code);const e=element('span','country-flag flag-'+code+(drawn?'':' fallback'),drawn?'':code);e.setAttribute('role','img');e.setAttribute('aria-label',p.nationality||'Ülke bilgisi yok');e.title=p.nationality||'Ülke bilgisi yok';return e;}
function message(text,error=false){$('game-message').textContent=text;$('game-message').classList.toggle('error',error);}
function closeSuggestions(){$('suggestions').hidden=true;$('player-search').setAttribute('aria-expanded','false');$('player-search').removeAttribute('aria-activedescendant');suggestions=[];activeIndex=-1;}
function search(){const query=normalizeName($('player-search').value);const list=$('suggestions');list.replaceChildren();if(!query){closeSuggestions();return;}
  const matches=findPlayers($('player-search').value,currentRoster(),round.guessIds);suggestions=matches.players;activeIndex=suggestions.length?0:-1;
  if(!suggestions.length){list.append(element('li','no-results','Bu isimle oyuncu bulunamadı. Havuzdaki başka bir ismi dene.'));}
  suggestions.forEach((p,i)=>{const li=element('li',i===0?'active':'');li.id='suggestion-'+i;li.setAttribute('role','option');li.setAttribute('aria-selected',i===0?'true':'false');li.append(flag(p));const info=element('div');info.append(element('strong','',p.name),element('small','',p.bonus?'ALBARAKA · Stajyer':p.club+' · '+(LEAGUES[p.league]||p.league||'')));li.append(info,element('span','suggestion-position',p.bonus?'BONUS':p.position||'—'));li.addEventListener('pointerdown',e=>e.preventDefault());li.addEventListener('click',()=>guess(p.id));list.append(li);});
  if(matches.total>suggestions.length)list.append(element('li','no-results',matches.total+' eşleşme · İlk '+suggestions.length+' gösteriliyor. Adı biraz daha yaz.'));
  list.hidden=false;$('player-search').setAttribute('aria-expanded','true');if(activeIndex>=0)$('player-search').setAttribute('aria-activedescendant','suggestion-'+activeIndex);
}
function moveSuggestion(step){if(!suggestions.length)return;activeIndex=(activeIndex+step+suggestions.length)%suggestions.length;[...$('suggestions').children].forEach((e,i)=>{e.classList.toggle('active',i===activeIndex);e.setAttribute('aria-selected',i===activeIndex?'true':'false');});$('player-search').setAttribute('aria-activedescendant','suggestion-'+activeIndex);$('suggestions').children[activeIndex].scrollIntoView({block:'nearest'});}
function startRound(){cancelReveal?.();revealing=false;const next=drawNext(eligible(),bag);if(!next.player){message('Bu ligde uygun oyuncu bulunamadı.',true);return;}bag=next.bag;round=createRound(next.player.id,round?.mode||'photo');roundNumber++;clueOpen=false;$('player-search').value='';closeSuggestions();message('');save();render();}
function guess(id){if(!round||round.status!=='playing'||revealing)return;if(round.guessIds.includes(id)){message('Bu oyuncuyu zaten denedin. Başka bir isim seç.',true);return;}try{round=submitGuess(round,id,currentRoster(),{asOf:data.snapshotDate});}catch{message('Listeden geçerli bir oyuncu seç.',true);return;}
  $('player-search').value='';closeSuggestions();if(round.status!=='playing'&&!isBonusRound(round)){stats.played++;if(round.status==='won'){stats.won++;stats.streak++;stats.bestStreak=Math.max(stats.streak,stats.bestStreak);stats.distribution[round.guessIds.length-1]++;sessionWins++;}else{stats.streak=0;}}
  revealing=true;message('İpuçları teker teker açılıyor…');save();render();const actions=[...revealActions];cancelReveal=revealSequence({onReveal:index=>actions[index]?.(),onComplete:()=>{revealing=false;cancelReveal=null;render();message(round.status==='playing'?(isBonusRound(round)?'İpuçları ve fotoğraf güncellendi. Bir sonraki tahminin ne?':'İpuçları geldi. Bir sonraki tahminin ne?'):'');if(round.status==='playing')$('player-search').focus();else $('result-panel').scrollIntoView({behavior:'smooth',block:'nearest'});}});
}
function render(){if(!round)return;const p=target(),bonus=isBonusRound(round),count=round.guessIds.length,done=round.status!=='playing'&&!revealing,photoCount=revealing?Math.max(0,count-1):count;
  document.body.classList.toggle('bonus-mode',bonus);$('bonus-note').hidden=!bonus;document.querySelector('#empty-state p').innerHTML=bonus?'Tahminlerin burada görünecek.<br>Fotoğraftan ve ipuçlarından tahmin et.':'Tahminlerin burada görünecek.<br>Her ipucu, gole bir adım daha yakın.';$('skip-bonus').hidden=!bonus||done;$('skip-bonus').disabled=revealing;$('clue-button').hidden=bonus;
  $('round-label').textContent=bonus?'ÖZEL DOSYA · AÇILIŞ BONUSU':'SCOUT DOSYASI #'+String(Math.max(1,roundNumber)).padStart(3,'0');$('attempt-number').textContent=String(done||revealing?count:Math.min(count+1,8)).padStart(2,'0');$('player-search').disabled=done||revealing;$('submit-guess').disabled=done||revealing;$('league').disabled=bonus||revealing;$('player-search').placeholder=revealing?'İpuçları açılıyor…':done?'Tur tamamlandı. Yeni oyuncu hazır!':bonus?'Bonus oyuncusunun adını yaz…':'Big 4’teki bir futbolcu adı yaz…';$('guess-history').setAttribute('aria-busy',String(revealing));document.querySelector('[data-dialog=stats]').disabled=revealing;
  $('mode-toggle').setAttribute('aria-pressed',round.mode==='hard'?'true':'false');$('mode-label').textContent=bonus?'Bonus portre':round.mode==='hard'?'Fotoğrafsız':'Fotoğraflı';$('mode-toggle').disabled=bonus||revealing||(count>0&&!done);$('mode-toggle').title=bonus?'Açılış bonusunda fotoğraf gösterilir.':count>0&&!done?'Bu tur başladı. Sonraki turda modu değiştirebilirsin.':'Fotoğraflı / fotoğrafsız oyna';
  const lives=$('lives');lives.replaceChildren();for(let i=0;i<8;i++)lives.append(element('span','life '+(done&&round.status==='won'?'won':i<count?'used':'available')));lives.setAttribute('aria-label',done?'Tur tamamlandı':(8-count)+' tahmin hakkı kaldı');
  const image=$('portrait');image.hidden=round.mode==='hard'&&!done;$('portrait-stage').classList.toggle('hard',round.mode==='hard'&&!done);const desired=new URL(p.photo.path,location.href).href;if(image.src!==desired){image.src=p.photo.path;image.dataset.failed='';}image.style.objectPosition=p.photo.objectPosition||'50% 0%';image.style.transform='scale('+(p.photo.scale||1.08)+')';image.style.transformOrigin=p.photo.transformOrigin||'50% 20%';image.style.filter=done?'none':'blur('+Math.max(2,12-photoCount*1.35)+'px)';image.alt=done?p.name+' portresi':'Tahmin edilecek futbolcunun bulanık portresi';
  $('portrait-placeholder').hidden=!(round.mode==='hard'&&!done)&&image.dataset.failed!=='true';if(round.mode==='hard'&&!done){$('portrait-placeholder').replaceChildren(element('span','','?'),element('p','','SADECE FUTBOL BİLGİN'));}else if(image.dataset.failed==='true'){$('portrait-placeholder').replaceChildren(element('span','','?'),element('p','image-error','FOTOĞRAF YÜKLENEMEDİ'));}
  $('portrait-stamp').textContent=done?p.name.toLocaleUpperCase('tr'):bonus?'BONUS · KİM BU?':'KİM BU FUTBOLCU?';$('portrait-stamp').classList.toggle('revealed-stamp',done);$('photo-caption').textContent=bonus?(done?'Bonus tamamlandı. Şimdi sıra Big 4’te.':'Özel açılış bonusu: Eren Çiftçi. Fotoğrafı tanıyabildin mi?'):done?'Dosya çözüldü. Sıradaki futbolcu seni bekliyor.':round.mode==='hard'?'Zor mod: fotoğraf yok, ipuçları var.':'Her yanlış tahminde fotoğraf biraz netleşir.';
  $('toolbar-title').textContent=bonus?'ÖZEL AÇILIŞ BONUSU':'BAŞLAMA VURUŞU';$('mini-tip-text').textContent=bonus?'Eren Çiftçi için ipuçlarını ve fotoğrafı kullanabilirsin; istersen bonusu geçebilirsin.':'Tanıdık gelmedi mi? Bir isimle başla, ipuçları seni doğru oyuncuya götürsün.';
  $('photo-dots').replaceChildren();for(let i=0;i<8;i++)$('photo-dots').append(element('span',i<count||done?'revealed':'','● '));
  $('clue-button').disabled=revealing||count<3||done||clueOpen;$('clue-note').textContent=clueOpen?'Açıldı':count<3?'3 tahminden sonra':'Ülke ipucu';$('clue-text').hidden=!clueOpen||done;if(clueOpen)$('clue-text').textContent='Ülke ipucu: '+p.nationality;
  $('empty-state').hidden=count>0;const history=$('guess-history');history.replaceChildren();revealActions=[];round.guessIds.forEach((id,i)=>history.append(guessCard(currentRoster().find(x=>x.id===id),round.comparisons[i],i+1,id===p.id,revealing&&i===count-1)));
  $('result-panel').hidden=!done;$('result-panel').classList.toggle('lost',round.status==='lost');$('next-round-label').textContent=bonus?'NORMAL OYUNA GEÇ':'YENİ FUTBOLCU';if(done){$('result-eyebrow').textContent=bonus?'ÖZEL AÇILIŞ BONUSU':round.status==='won'?'GOL! SCOUT GÖREVİ TAMAMLANDI':'SON DÜDÜK';$('result-title').textContent=bonus?(round.status==='won'?'Bonusun yıldızını buldun: Eren Çiftçi!':'Bonusun yıldızı: Eren Çiftçi.'):round.status==='won'?'İşte gerçek bir scout!':'Bu kez direkten döndü.';$('result-details').textContent=bonus?'Eren Çiftçi · ALBARAKA · Türkiye · Stajyer · 22 yaş · #37 · Bonus tur skor tablosuna eklenmez. Şimdi '+players.length+' futbolcuyla normal oyun başlıyor.':p.name+' · '+p.club+' · '+p.nationality+' · '+POSITIONS[p.position]+' · '+ageOn(p.birthDate,data.snapshotDate)+' yaş · #'+p.shirtNumber+(round.status==='won'?' — '+count+'/8 tahminde buldun.':' — Yeni turda tekrar dene.');}
  $('pool-size').textContent=bonus?'AÇILIŞ BONUSU · '+players.length+' FUTBOLCU HAZIR':eligible().length+' PORTRE · '+searchPlayers.length.toLocaleString('tr')+' OYUNCU ARAMADA';$('pool-size').title='Portre havuzu: '+players.length+' · Arama: Big 4’ün '+data.coverage.completedTeamCount+' kulübündeki oyuncular';$('search-count').textContent=bonus?'Eren Çiftçi veya ipucu için bir futbolcu ara.':searchPlayers.length.toLocaleString('tr')+' oyuncu arasından seç. Tüm Big 4 kadroları.';$('session-score').textContent='BU OTURUM · '+(sessionWins-(revealing&&round.status==='won'&&!bonus?1:0))+' GOL';
}
function guessCard(p,comparison,index,correct,masked=false){const card=element('article','guess-card'+(masked?' new-guess':''));const head=element('div','guess-card-header');head.append(element('span','guess-order',String(index).padStart(2,'0')));const name=element('div');name.append(element('strong','',p.name),element('small','',p.club));head.append(name);if(correct&&!masked)head.append(element('span','guess-status','✓ BULUNDU'));card.append(head);const grid=element('div','feedback-grid');
  const categories=[['club','KULÜP',p.club],['nationality','ÜLKE',p.nationalityCode],['position','MEVKİ',p.position],['age','YAŞ',ageOn(p.birthDate,data.snapshotDate)],['shirt','FORMA',p.shirtNumber]];
  for(const [key,label,value]of categories){const original=comparison[key];const unknown=value==null;const info=unknown?{...original,status:'unknown',direction:null}:original;const cell=element('div','feedback-cell');const reveal=()=>{cell.replaceChildren();cell.className='feedback-cell '+info.status+(masked?' cell-flip':'');let display=key==='nationality'&&!unknown?flag(p):element('span','cell-value'+(key==='club'?' club-value':''),value==null?'—':String(value));if(key==='nationality'&&!unknown){display.classList.add('cell-value');display.title=p.nationality||'Bilgi yok';}if(info.direction)display.append(element('span','direction',info.direction==='up'?'↑':'↓'));cell.append(display,element('span','cell-label',label));const description=unknown?'Bilgi yok':(key==='position'?POSITIONS[p.position]:key==='nationality'?p.nationality:value)??'Bilgi yok';cell.title=description+' — '+COLORS[info.status]+(info.direction?' · Aranan oyuncunun '+(key==='age'?'yaşı':'forma numarası')+' daha '+(info.direction==='up'?'yüksek':'düşük'):'');cell.setAttribute('aria-label',label+': '+description+', '+COLORS[info.status]+(info.direction?', '+(info.direction==='up'?'daha yüksek':'daha düşük')+' olmalı':''));};if(masked){cell.classList.add('cell-pending');cell.append(element('span','pending-mark','?'),element('span','cell-label',label));cell.setAttribute('aria-label',label+': henüz açılmadı');revealActions.push(reveal);}else reveal();grid.append(cell);}card.append(grid);return card;}
function dialog(type){const content=$('dialog-content');content.replaceChildren();$('dialog-label').textContent='PIXEL SCOUT · '+({help:'OYUN KİTABI',stats:'SKOR TABELASI',credits:'KAYNAKLAR'}[type]||'');
  if(type==='help'){content.append(element('h2','','Sahaya hoş geldin.'));content.append(element('p','modal-callout','Her açılış Bonus Oyuncu bonusuyla başlar. Özellikleri bilinmiyor; istersen bonusu geç. Bu tur normal istatistiklere eklenmez.'));const ol=element('ol');['Bulanık portredeki futbolcuyu 8 tahminde bul. İstersen ilk tahminden önce fotoğrafsız moda geç.','Oyuncunun adını yaz ve öneri listesinden seç. Enter ile seçili öneriyi gönderebilirsin.','Yeşil hücre doğru bilgiyi gösterir. Sarı kulüp hücresi aynı ligde farklı bir kulüp demektir.','Yaş ve forma okları aranan oyuncunun değerine yönelir: ↑ daha yüksek, ↓ daha düşük.','Üç tahminden sonra isteğe bağlı ülke ipucunu açabilirsin.','Kazansan da kaybetsen de hemen yeni tura geç. Havuz bitene kadar oyuncular tekrarlanmaz.'].forEach(t=>ol.append(element('li','',t)));content.append(ol,element('p','',players.length+' tanınmış futbolcunun portresi hedef olabilir. Tahmin listesi ise Big 4’ün '+searchPlayers.length.toLocaleString('tr')+' oyuncusunu kapsar; portresi olmayan bir oyuncuyu da deneyebilirsin.'),element('p','modal-callout','Lig değiştirmek yeni bir tur başlatır. Mevki grupları: GK kaleci, DF defans, MF orta saha, FW forvet.'),element('p','data-note','2026/27 oyuncu bilgileri · ' + new Intl.DateTimeFormat('tr',{day:'numeric',month:'long',year:'numeric'}).format(new Date(data.snapshotDate+'T12:00:00Z')) + ' tarihinde doğrulandı. Yaşlar bu veri tarihine göre hesaplanır.'));
  }else if(type==='stats'){content.append(element('h2','','Senin skor tabelan.'));const grid=element('div','stat-grid');[[stats.played,'OYNANAN'],[stats.played?Math.round(stats.won/stats.played*100)+'%':'0%','GALİBİYET'],[stats.streak,'SERİ'],[stats.bestStreak,'EN İYİ SERİ']].forEach(([n,l])=>{const box=element('div','stat-box');box.append(element('strong','',n),element('span','',l));grid.append(box);});content.append(grid,element('h3','','Tahmin dağılımı'));const max=Math.max(1,...stats.distribution);stats.distribution.forEach((n,i)=>{const row=element('div','distribution');const bar=element('div','distribution-bar',n);bar.style.width=Math.max(8,n/max*85)+'%';row.append(element('span','',i+1),bar);content.append(row);});content.append(element('p','data-note',storageAvailable?'İstatistikler bu tarayıcıda saklanır. Yarım bırakılan turlar sayılmaz.':'Bu tarayıcı kayıt izni vermediği için istatistikler oturum boyunca tutulur.'));
  }else if(type==='credits'){content.append(element('h2','','Gerçek yüzler. Açık kaynaklar.'),element('p','','Portreler Wikimedia Commons’tan, ücretsiz kullanım koşulları kontrol edilerek seçildi. Fotoğraflar oyun alanında yakın kadrajla gösterilir ve tahminler sırasında bulanıklaştırılır. CC BY-SA görsellerindeki uyarlamalar kaynak fotoğrafın lisans koşullarıyla sunulur.'));content.append(element('p','modal-callout','Açılış bonusu: Bonus Oyuncu. Bu kurgusal demo için orijinal SVG kullanılır; futbolcu özellikleri bilinmiyor.'));const list=element('div','credits-list');players.forEach(p=>{const item=element('div','credit-item');item.append(element('strong','',p.name),element('p','',p.photo.author+' · '+p.photo.license));const source=element('a','','Fotoğraf kaynağı');source.href=p.photo.sourcePage;source.target='_blank';source.rel='noopener noreferrer';item.append(source);if(p.photo.licenseUrl){const license=element('a','',' · Lisans');license.href=p.photo.licenseUrl;license.target='_blank';license.rel='noopener noreferrer';item.append(license);}const facts=element('a','',' · Oyuncu bilgileri');facts.href=p.sourceUrls[0];facts.target='_blank';facts.rel='noopener noreferrer';item.append(facts);list.append(item);});content.append(list);const fontNote=element('p','data-note','Silkscreen yazı tipi: Jason Kottke · SIL Open Font License 1.1. ');const license=element('a','','Yazı tipi lisansı');license.href='assets/Silkscreen-OFL.txt';license.target='_blank';fontNote.append(license);content.append(fontNote,element('p','data-note','Oyuncu verileri ' + data.snapshotDate + ' tarihli 2026/27 sezonu görünümüne sabitlenmiştir. Arama kataloğu Big 4’ün tüm ' + data.coverage.completedTeamCount + ' kulübünün kaynakta listelenen kadrolarını kapsar; kaynakta olmayan bilgiler — olarak gösterilir. Bu bağımsız oyun herhangi bir kulüp veya lig tarafından desteklenmemektedir.'));}
  $('modal').showModal();
}
document.querySelectorAll('[data-dialog]').forEach(button=>button.addEventListener('click',()=>dialog(button.dataset.dialog)));$('close-dialog').addEventListener('click',()=>$('modal').close());$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const rect=$('modal').getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)$('modal').close();}});
$('player-search').addEventListener('input',search);$('player-search').addEventListener('keydown',e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if($('suggestions').hidden)search();else moveSuggestion(e.key==='ArrowDown'?1:-1);}if(e.key==='Escape')closeSuggestions();});
document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))closeSuggestions();});$('guess-form').addEventListener('submit',e=>{e.preventDefault();if(round?.status!=='playing'||revealing)return;const query=normalizeName($('player-search').value);if(!query){message('Önce bir futbolcu adı yaz.',true);return;}if(suggestions[activeIndex]){guess(suggestions[activeIndex].id);return;}const duplicate=currentRoster().find(p=>[p.name,...p.aliases].some(a=>normalizeName(a)===query)&&round.guessIds.includes(p.id));if(duplicate){message('Bu oyuncuyu zaten denedin. Başka bir isim seç.',true);return;}if(suggestions[activeIndex])guess(suggestions[activeIndex].id);else{const exact=currentRoster().find(p=>normalizeName(p.name)===query||p.aliases.some(a=>normalizeName(a)===query));if(exact)guess(exact.id);else message('Öneri listesinden bir oyuncu seç.',true);}});
$('skip-bonus').addEventListener('click',()=>{if(isBonusRound(round)&&!revealing){startRound();$('player-search').focus();}});$('next-round').addEventListener('click',()=>{startRound();$('player-search').focus();$('guess-form')?.scrollIntoView({block:'nearest'});});$('league').addEventListener('change',()=>{league=$('league').value;startRound();message('Yeni lig, yeni oyuncu. Başlama vuruşu sende.');});$('mode-toggle').addEventListener('click',()=>{if(!round||isBonusRound(round))return;if(round.status!=='playing'){round.mode=round.mode==='photo'?'hard':'photo';startRound();}else{round.mode=round.mode==='photo'?'hard':'photo';save();render();}});$('clue-button').addEventListener('click',()=>{if(!isBonusRound(round)&&round.guessIds.length>=3&&round.status==='playing'){clueOpen=true;save();render();}});
$('share-result').addEventListener('click',async()=>{const emoji={exact:'🟩',league:'🟨',miss:'⬜'};const rows=round.comparisons.map(c=>Object.values(c).map(v=>emoji[v.status]).join('')).join('\n');const text=isBonusRound(round)?'Pixel Scout · Açılış bonusu · '+(round.status==='won'?round.guessIds.length:'X')+'/8\nEren Çiftçi\n'+location.origin:'Pixel Scout · '+(round.mode==='hard'?'Fotoğrafsız':'Fotoğraflı')+' · '+(round.status==='won'?round.guessIds.length:'X')+'/8\n'+rows+'\nSınırsız futbolcu tahmini\n'+location.origin;try{await navigator.clipboard.writeText(text);$('share-result').textContent='Kopyalandı ✓';setTimeout(()=>$('share-result').textContent='Sonucu kopyala',2200);}catch{const area=element('textarea');area.value=text;area.setAttribute('aria-label','Kopyalanacak sonuç');$('dialog-content').replaceChildren(element('h2','','Sonucunu paylaş.'),element('p','','Sonucu seçip kopyalayabilirsin.'),area);$('modal').showModal();area.select();}});
$('portrait').addEventListener('error',()=>{$('portrait').dataset.failed='true';$('portrait-placeholder').hidden=false;$('portrait-placeholder').replaceChildren(element('span','','?'),element('p','image-error','FOTOĞRAF YÜKLENEMEDİ'));message('Fotoğraf yüklenemedi. Sayfayı yenileyebilir veya ipuçlarıyla devam edebilirsin.',true);});$('portrait').addEventListener('load',()=>{$('portrait').dataset.failed='';if(round?.mode==='photo'||round?.status!=='playing')$('portrait-placeholder').hidden=true;});
['contextmenu','dragstart','selectstart'].forEach(type=>{
  $('portrait')?.addEventListener(type,e=>e.preventDefault());
  $('portrait-shield')?.addEventListener(type,e=>e.preventDefault());
  $('portrait-stage')?.addEventListener(type,e=>e.preventDefault());
});
function beginBonus(){cancelReveal?.();revealing=false;cancelReveal=null;round=openingRound();league='all';clueOpen=false;$('league').value='all';$('player-search').value='';closeSuggestions();message('');save();render();}
async function init(){try{const response=await fetch('./players.json');if(!response.ok)throw Error('Data unavailable');data=await response.json();players=data.players;searchPlayers=data.searchPlayers;if(!players?.length||!searchPlayers?.length)throw Error('Empty pool');const saved=readStorage();stats=cleanStats(saved.stats);if(saved.snapshotDate===data.snapshotDate){bag=saved.bag||{};roundNumber=Number.isSafeInteger(saved.roundNumber)&&saved.roundNumber>0?saved.roundNumber:0;}beginBonus();}catch(error){message('Oyuncu havuzu yüklenemedi. Bağlantını kontrol edip sayfayı yenile.',true);$('portrait-placeholder').replaceChildren(element('span','','!'),element('p','','BAĞLANTIYI KONTROL ET'));console.error('Game initialization failed:',error);}}
window.addEventListener('pageshow',event=>{if(event.persisted&&players.length)beginBonus();});
init();
